import {BACKOFFICE_ROLES_V28} from './roles-v28.js';

// These fictional futures extend the existing catalog without inserting cards
// into the order used by published saves and anonymous collections.
const work={
 finance:{tool:'資金預估、付款安排與應收追蹤',memory:'銀行餘額沒有因為願景會議而多一位數。',future:'替小團隊整理現金流與付款規劃，先寫明服務範圍'},
 accounting:{tool:'核銷憑證、薪資對帳與月結底稿',memory:'你記得每一次「先幫我過」，也記得最後是誰要在帳上留下名字。',future:'替小團隊整理帳務流程，該由合格專業人士承接的部分就交給對方'},
 hr:{tool:'招募承諾、出勤紀錄與人事往來',memory:'咖啡可以重泡，人事文件上的一句話卻不能當作沒寫過。',future:'接範圍清楚的招募與人事流程顧問工作，不把別人的一句急件排滿自己整週'},
 admin:{tool:'採購比價、總務交接與那些臨時多出來的人事工作',memory:'你的待辦曾經同時有咖啡、門禁和招募，唯獨沒有自己的下班時間。',future:'幫小團隊整理行政採購與日常流程，臨時追加的工作另排時間'}
};
const pages={
 fired_signed:['紙上先離職的人','門禁失效了，紙上卻是你自己要走。','對方把文件推過來，說簽完比較好處理。你在混亂裡簽了字，回家才把那幾行重新讀完。這張紙沒有替整段工作下定論，你把自己的紀錄收好，決定先弄清楚接下來能做什麼。'],
 fired_refused:['這一欄，我先不簽','離場可以安排，理由不能替你寫。','法師問你為什麼不配合，真真看著時間，阿福已經在等設備點交。你只說這不是自己提出的離職，把文件與對話記下來。門禁仍會被收回，你說過什麼卻沒有一起交出去。'],
 layoff:['下一張表，沒有你的座位','沒有改善期，只有設備點交單。','昨天的工作還排到下週，今天先收到離場通知。法師、真真與阿福逐項確認設備，你請對方把處理方式寫清楚。公司的行事曆仍然很滿，從這天起卻不再有權替你排下一個晚上。'],
 pip_fail:['考卷換了，期限沒換','這輪改善沒有換到留下來。','你照著目標補紀錄，下一次談話又多了一條沒寫過的期待。希望說結果已經確認，你把這一輪的版本依序存好。這個結尾不是對你全部能力的評分，只是這份工作終於停止追加下一題。'],
 pip_exit:['先通過，再離開','過關證明做得到，離開證明可以自己選。','改善期結束，希望確認這次通過。翅膀沒有因此忽然欣賞你的問題，你也沒有再等下一句肯定。離職信上寫好日期，完成交接後，你把通過紀錄留給自己。'],
 ragequit:['這次不再回座位','最後一件交辦，是把自己帶出去。','翅膀還在說事情總要有人做，你已經把待辦和交接窗口寄出。這不是一場漂亮的結案會議，你的手也還在抖；但走出電梯後，今天剩下的時間終於不必再等一則訊息批准。'],
 burnout:['表格還能開，人先關機','下一個急件，身體已經沒有回覆。','你一直想把這件做完再休息，工作卻總能接出下一件。這天連最熟悉的清單都看不進去，你把求助和休息排在交付前面。事情會有人重新安排，這次先別讓自己的名字只剩待辦窗口。'],
 broke:['存款比耐心先用完','願景沒有轉帳，帳單照常入帳。','你算完這段日子的生活支出，發現能再撐多久已經不能靠「公司快好了」回答。這次先停止拿自己的存款補工作留下的缺口，找能維持生活的安排。重新開始不光彩嗎？至少這回的數字是自己的。'],
 assistant:['專員缺，助理價','少的是職稱與薪水，多的還是工作。','錄取信談過的專業，一直被留到「以後再說」。你已經能獨立做事，名片卻仍像一張等待核准的便條。離開前你把真正完成的工作寫進履歷，沒有再用那張比較便宜的名片替自己作證。'],
 nasdaq:['敲鐘之前，先核對這一筆','平行宇宙裡，願景真的對上了帳。','這是幻想結局：移動真的在納斯達克敲鐘。翅膀笑著說一路走來不容易，你在合照前先確認輪到自己的部分有沒有寫進文件。鐘聲是真的，這回回家後也真的不用再等一句「之後一起算」。'],
 taiwan:['掛牌了，這次不是海報','平行宇宙裡，股票不只出現在簡報。','這是幻想結局：公司真的走完掛牌流程。群組的鞭炮貼圖比月結訊息還密，你把過去那些寫著未來的檔案一份份關掉。站上台之前，先替自己留好能核對的那份條件；這次好消息終於有了日期。'],
 acquired:['交接給下一家公司','有人接下公司，你接回自己的選擇。','這是幻想結局：收購案真的成立，新的窗口開始逐項核對人力與責任。你把自己手上那份流程講清楚，也把想留下與不想再接的工作說明白。合約不是魔法，至少下一輪不用全靠猜翅膀今天的心情。'],
 promotion:['名片變大，桌子沒變','職稱多了，授權還得另外問。','升遷通知來了，新的責任比新名片先送到。你沒有把每一句恭喜都換成無限待命，先把資源、決策權和交付逐項談清楚。這一階不是永久勝利，卻是你實際做過、也能帶走的一段工作。'],
 slacker:['忙碌之外，保住自己','工作會做，無限追加不會全收。','你學會辨認哪些事真急，哪些只是語氣很急。清單照做，能批次處理就不把自己切成十份；下班時間到了，手機也有自己的休息。翅膀偶爾問你怎麼看起來不忙，你決定不要把這個問題也排成工作。'],
 sycophant:['報表最後一欄叫遠見','數字可以討論，句尾先補一句都是您帶得好。','你熟悉翅膀喜歡聽的順序：先方向正確，再補今天的進度。名片往上換，同事的真話卻越來越短。這段人生走得順，並不代表每一句附和都沒有代價；離場時，你第一次有空重讀自己寫過的那些讚美。'],
 historian:['附件裡還有另一個版本','檔案可以改名，時間順序還在。','你把能公開的經歷去識別整理，留下當時怎麼說、後來怎麼改，也分清親眼所見和沒有確認的傳聞。前同事看見熟悉的節奏笑了出來。這次你不必替誰結案，只把自己的那一頁寫清楚。'],
 career_assistant:['助理那一格，也有名字','做過的事，不會因為字比較小就不算。','你以助理身分做完這一段工作，學到流程，也學到哪些「先幫一下」需要留紀錄。你沒有等到每個人都同意你值得更好的安排才離開。履歷上的第一格，由自己寫下真正做過的事。'],
 career_staff:['把專業那一格寫完整','不是每一段工作都得換成主管椅。','你把能獨立完成的工作、做過的判斷和交付整理好。這次沒有替自己預約下一輪升遷，也沒有為此道歉。以專業員工的經歷離開，仍然是一段完整的職涯。'],
 career_senior:['資深，不等於無限轉接','經驗留下來，急件不用全部跟著走。','你能看出問題卡在哪，也開始知道如何讓同事自己接著做。離場前留下的是方法與範圍，不是一支永久開機的私人客服電話。資深兩個字記下你做過的判斷，沒有簽走你之後所有晚上。'],
 career_principal:['主任先把專業守住','能拍板的地方，先有能說明的依據。','你曾在會議裡替不合理的承諾踩煞車，也曾把重要決定寫到別人看得懂。這次帶走的不只是職級，還有那些沒有被一句「先做再說」沖掉的判斷。交接完成，最後一頁不必再等翅膀評語。'],
 career_deputy:['小組交回去，自己留下來','副理的工作做過了，下一段不必照舊。','你排過工作，也替同事接過第一輪追問。卸下這一段責任前，把誰接手、哪些事仍缺人寫清楚，沒有拿一句團隊會撐住填滿空格。離開那張主管椅時，肩膀終於知道今天可以放下什麼。'],
 career_manager:['經理的最後一張人力表','最後一個要排好的，是自己。','你管過人力、績效和那些沒有預算的承諾，也記得誰真的把工作做完。這次交接沒有只留一張組織圖，缺口與責任都逐項留下。走到門口，你不再是下一場救火會議的預設主持人。'],
 career_director:['部門看完，門外也有路','總監的視野，這次包含自己的生活。','你曾把部門的預算、人力和承諾放在同一張圖，也曾拒絕把缺人寫成同事不夠努力。離開前留下真正能接下去的安排。圖上不再有你的座位，門外卻仍有你願意做的事。'],
 career_chief:['這次由自己簽下離席','坐過高層的位置，也有權決定不再坐。','你真的走到高層，知道一個簽名會把多少工作送到別人桌上。這次沒有用更大的願景把自己繼續綁住，留下交接與應負的責任後正式離席。職稱仍能寫進履歷，人生卻不用繼續印在同一張名片上。'],
 second_offer:['下一份條件，這次先問完','錄取通知不再只看最粗的那一行。','前同事幫你核對新機會，你把薪資、工作範圍和匯報窗口一項項問清楚。對方願意寫下來，你才回簽。新工作不保證沒有難題，至少這一次，不必報到後才猜自己究竟被錄取來做什麼。'],
 handover_author:['說明書會更新，離職日不會','交接有截止日，幫忙也有範圍。','你把未完成事項、文件位置和接手窗口整理到別人能照著做。對方又問離職後能不能隨時聯絡，你把支援截止日指給他看。交接完整不等於終身維護，這一頁終於真的翻過去。'],
 alumni_network:['名片之外，還認得彼此','離職群組第一次只需要問晚餐吃什麼。','一起上過班的人仍會交換工作消息，也會記得誰曾幫自己把話說清楚。你們約了一頓不用報進度的飯，聊到熟悉的插單又笑出來。公司留不住的關係，沒有因此一起失效。'],
 consultant:['先談範圍，再談顧問','熟悉流程，不代表永久免費待命。','對方想用顧問方式繼續合作，你把交付、時數和另外計費的項目逐一列出。不是每個人都喜歡看到範圍，但願意合作的人看得懂。這次你的專業仍能幫忙，行事曆卻由自己批准。'],
 merged_out:['格子被刪，經歷沒有','新組織圖沒有你，下一張履歷有。','部門調整後，你的工作被拆進不同窗口。你把仍需要有人負責的部分逐項交接，不替空白的人力安排保證一切正常。組織圖上那一格消失了，做過的事卻沒有被同一張紙刪掉。'],
 rage_legal:['失控之後，照程序面對','那一下沒有替任何人取消責任。','真正的衝突發生後，你停止再動手，整理經過，也面對後續程序與自己該承擔的部分。沒有一場勝利音樂替事情結案。回到能好好說話的位置，是這段失控之後仍要自己走的路。'],
 rage_defeated:['氣勢先出去，人被勸回來','失控沒有想像中的英雄分鏡。','你以為怒氣能替自己撐場，現實卻沒有照腦內畫面發展。衝突被叫停，你也得處理受傷、道歉和接下來的安排。那一刻終於明白，離開這份工作有別的路，不必每一條都經過這一拳。'],
 rage_coup:['平行宇宙的換椅子大會','這個荒謬的世界，真的讓你坐上去了。','這是失控後的幻想分支：一連串不可能的會議之後，管理位置竟然換到你這一邊。你看著整桌簽核，第一個決定是替所有人保留拒絕的空間。故事可以胡鬧，現實中的衝突仍不會因此變成捷徑。'],
 rage_truce:['先把拳頭放下來','沒有贏家，還有下一步。','衝突被同事叫停，雙方終於分開坐下。你沒有立刻得到想要的公道，也沒有再用下一次失控補上一句話。先把自己安頓好，留下能處理的紀錄；這回結束在仍有辦法往前走的位置。'],
 rage_meme:['梗圖沒有替你結案','群組很熱鬧，後續仍得自己面對。','失控畫面在這個荒謬分支裡變成迷因，轉傳比工作群組的訊息還快。你笑不太出來，因為後續並沒有隨貼圖消失。收起手機後，你開始處理真正在自己生活裡留下來的部分。'],
 rage_walkaway:['這次離場，不再補一拳','還能決定下一步，就先把自己帶走。','你在衝突繼續升高前停下來，把需要處理的後續交給適合的窗口。這不是把事情當作沒發生，而是不再用下一次失控追加代價。離開電梯時，手終於鬆開，往後的路不用再靠怒氣帶著走。'],
 cold_storage:['三樓沒有工作，門外還有','被收走的待辦，不等於被收走的人生。','辦公室在五樓，你卻被安排到三樓待命。你記下沒有交辦的日子，也把能整理的經歷和下一站準備好。離開時不必感謝這種安排；那部電梯不是唯一能往上走的路。'],
 mediation_settled:['這次把條件寫下來','好聚好散，不能只剩一句好聽話。','你帶著紀錄，把雙方能接受的部分逐項確認，這一輪終於有了書面條件。這段虛構故事沒有替任何現實爭議預告結果，只讓你不必再每天等公司換一句說法。文件收好，接下來的生活慢慢排。'],
 mediation_pending:['這一頁，先留未成立','沒有為了讓會議好看就說自己沒事。','這次協商沒有成立，你把來回文件與會議紀錄收在一起，先確認能做的下一步。這不是故事替現實程序下了結論，也不是你必須立刻放下的期限。沒有結案的一頁，仍可以留著自己的版本。'],
 venture_independent:['自己開張，收入也自己核對','這次的小生意，不用先改變世界。','你離職後開起自己的小工作室，把範圍、付款和休息日寫清楚。第一批案子做得完，也真的收到了款。規模還小，決定卻能對得上日子；不必先敲鐘，第一張付清的帳單已經很好聽。'],
 venture_restart:['關掉這一輪，留下下一輪','生意沒站穩，自己沒有全部押進去。','你真的離職，也真的投入這輪生意。訂單與回款沒有照計畫來，你在生活預備金還夠時停下追加，把成本和經驗收好。創業沒有因此變成失敗者的身分；這只是這一次結束，下次仍有自己的選擇。'],
 retired_free:['明天先不設鬧鐘','這次的休息，不用填申請單。','你交回設備，關掉工作提醒，存下來的餘裕讓今天不用再靠忍耐換薪水。早上慢慢吃完早餐，下午可以沒有進度。這個結尾沒有替現實退休規劃作保，只把這段人生的時間，正式交還到你自己手上。'],
 retired_flexible:['有空才接，不接也行','專業還在，全天待命已經退訂。','你離開全職工作，只留下自己願意接的小型合作。先談範圍與時間，做完就收工，不合適的邀請可以笑著放回桌上。存款替這段人生留下選擇，行事曆也終於能空著，而不是每格都等別人填滿。']
};

export function backofficeEndingsV28(families){
 return families.flatMap(family=>BACKOFFICE_ROLES_V28.map(role=>{
  const [title,subtitle,body]=pages[family.id];
  const detail=work[role.id];
  return {id:`${family.id}-${role.id}`,family:family.id,roleId:role.id,type:family.type,minRules:28,
   title:`${role.name}｜${title}`,subtitle,body:`你從${role.name}的錄取信開始，帶走的不只是${detail.tool}。${detail.memory}${body}${family.id==='venture_independent'?`你現在想${detail.future}，每一筆新增工作都可以重新談。`:''}`,
   symbol:family.id.startsWith('career_')?'階':family.id.startsWith('retired_')?'閒':family.id.startsWith('venture_')?'創':role.symbol,
   hint:`新人生應徵${role.name}，完成「${family.label}」的實際離場條件。`};
 }));
}
